package com.alokrathava.sdk.model

/**
 * Represents a 2D occupancy grid map generated by SLAM or loaded from the robot.
 * Contains map dimensions, grid resolution (meters/cell), origin pose in world coordinates,
 * and cell probability values (-1 = unknown, 0 = free, 100 = occupied).
 */
data class RobotOccupancyGrid(
    val mapId: String = "",
    val widthCells: Int = 0,
    val heightCells: Int = 0,
    val resolutionMetersPerCell: Double = 0.05,
    val originX: Double = 0.0,
    val originY: Double = 0.0,
    val originYaw: Double = 0.0,
    val data: ByteArray = byteArrayOf()
) {
    /** Returns true if the occupancy grid contains non-empty dimension data. */
    val isValid: Boolean get() = widthCells > 0 && heightCells > 0 && data.isNotEmpty()

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as RobotOccupancyGrid

        if (mapId != other.mapId) return false
        if (widthCells != other.widthCells) return false
        if (heightCells != other.heightCells) return false
        if (resolutionMetersPerCell != other.resolutionMetersPerCell) return false
        if (originX != other.originX) return false
        if (originY != other.originY) return false
        if (originYaw != other.originYaw) return false
        if (!data.contentEquals(other.data)) return false

        return true
    }

    override fun hashCode(): Int {
        var result = mapId.hashCode()
        result = 31 * result + widthCells
        result = 31 * result + heightCells
        result = 31 * result + resolutionMetersPerCell.hashCode()
        result = 31 * result + originX.hashCode()
        result = 31 * result + originY.hashCode()
        result = 31 * result + originYaw.hashCode()
        result = 31 * result + data.contentHashCode()
        return result
    }
}
